// Construye la solicitud HTTP a OpenAI según la operación del puerto (llm.complete | llm.transcribe | embeddings.embed)
const r = $json;
const s = r.settings || {};
const inp = r.input || {};
const base = (s.base_url || 'https://api.openai.com/v1').replace(/\/$/, '');
let url, body;
if (r.port === 'llm' && r.operation === 'complete') {
  url = base + '/chat/completions';
  body = { model: inp.model || s.default_model, messages: inp.messages || [] };
  if (!body.model) { return { json: { skip: true, status: 'PERMANENT_ERROR', error: { code: 'VALIDATION', message: 'llm.complete sin modelo (input.model o settings.default_model)' } } }; }
  if (inp.max_output_tokens) body.max_completion_tokens = inp.max_output_tokens;
  if (inp.temperature !== undefined && inp.temperature !== null) body.temperature = inp.temperature;
  const effort = inp.reasoning_effort || s.default_reasoning_effort;
  if (effort) body.reasoning_effort = effort;
  if (inp.response_format && inp.response_format.type === 'json_schema') {
    body.response_format = { type: 'json_schema', json_schema: { name: inp.response_format.name || 'respuesta', schema: inp.response_format.schema, strict: true } };
  } else if (inp.response_format && inp.response_format.type === 'json_object') {
    body.response_format = { type: 'json_object' };
  }
} else if (r.port === 'embeddings' && r.operation === 'embed') {
  url = base + '/embeddings';
  body = { model: inp.model || s.model, input: inp.texts || [] };
  if (s.dimensions) body.dimensions = s.dimensions;
  if (!body.model) { return { json: { skip: true, status: 'PERMANENT_ERROR', error: { code: 'VALIDATION', message: 'embeddings.embed sin modelo (input.model o settings.model)' } } }; }
} else if (r.port === 'llm' && r.operation === 'transcribe') {
  // Nota de voz → texto (lote 12, D-65). El audio llega en base64 (input.audio_base64) y se envía como multipart.
  const model = inp.model || s.transcribe_model;
  if (!model) { return { json: { skip: true, status: 'PERMANENT_ERROR', error: { code: 'VALIDATION', message: 'llm.transcribe sin modelo (input.model o settings.transcribe_model)' } } }; }
  if (!inp.audio_base64) { return { json: { skip: true, status: 'PERMANENT_ERROR', error: { code: 'VALIDATION', message: 'llm.transcribe sin input.audio_base64' } } }; }
  return { json: { skip: false, multipart: true, url: base + '/audio/transcriptions', model, language: inp.language || s.transcribe_language || 'es',
                   timeout_ms: s.timeout_ms || 30000, started: Date.now() },
           binary: { file: { data: inp.audio_base64, mimeType: inp.mime_type || 'audio/ogg', fileName: inp.filename || 'audio.ogg' } } };
} else {
  return { json: { skip: true, status: 'NOT_SUPPORTED', error: { code: 'OPERATION_NOT_SUPPORTED', message: r.port + '.' + r.operation } } };
}
return { json: { skip: false, url, body, timeout_ms: s.timeout_ms || 30000, started: Date.now() } };

// Normaliza la respuesta de OpenAI al contrato del puerto
const req = $('Solicitud del puerto').item.json;
const s = req.settings || {};
const res = $json;
const code = res.statusCode;
const body = res.body || {};
if (code >= 200 && code < 300) {
  // Precio: modelo devuelto, modelo pedido, modelo por defecto o, si el proveedor devuelve una instantánea
  // (p. ej. "gpt-6-luna-2026-09-22"), la clave más larga que sea prefijo del modelo devuelto.
  const prices = s.pricing || {};
  const prefixKey = Object.keys(prices).filter(k => String(body.model || '').startsWith(k)).sort((a, b) => b.length - a.length)[0];
  const pricing = prices[body.model] || (prefixKey ? prices[prefixKey] : null) || prices[req.input?.model] || prices[s.default_model] || prices[s.model] || null;
  if (req.port === 'llm' && req.operation === 'transcribe') {
    // usage: {type: 'tokens', input_tokens, output_tokens} o {type: 'duration', seconds}, según el modelo
    const u = body.usage || {};
    const tp = prices[req.input?.model] || prices[s.transcribe_model] || pricing;
    let tcost = null;
    if (tp && u.type === 'duration' && tp.per_minute !== undefined) tcost = (u.seconds || 0) / 60 * tp.per_minute;
    else if (tp && u.input_tokens !== undefined && tp.input_per_1m !== undefined) tcost = ((u.input_tokens || 0) * tp.input_per_1m + (u.output_tokens || 0) * (tp.output_per_1m || 0)) / 1e6;
    return { json: { status: 'OK', data: { text: body.text ?? '', model: req.input?.model || s.transcribe_model, language: body.language ?? null },
                     usage: { input_tokens: u.input_tokens ?? 0, output_tokens: u.output_tokens ?? 0, seconds: u.seconds ?? null }, cost_usd: tcost, error: null } };
  }
  if (req.port === 'llm') {
    const choice = (body.choices || [])[0] || {};
    const content = choice.message?.content ?? '';
    let parsed = null;
    if (req.input?.response_format && ['json_schema', 'json_object'].includes(req.input.response_format.type)) {
      try { parsed = JSON.parse(content); } catch (e) { return { json: { status: 'PERMANENT_ERROR', data: { content }, error: { code: 'INVALID_JSON_OUTPUT', message: 'el modelo no devolvió JSON válido' } } }; }
    }
    const cached = body.usage?.prompt_tokens_details?.cached_tokens ?? 0;
    const usage = { input_tokens: body.usage?.prompt_tokens ?? 0, output_tokens: body.usage?.completion_tokens ?? 0, cached_input_tokens: cached,
                    reasoning_tokens: body.usage?.completion_tokens_details?.reasoning_tokens ?? 0 };
    // Los tokens de razonamiento ya vienen dentro de completion_tokens (se cobran como salida).
    const cachedRate = pricing && pricing.cached_input_per_1m !== undefined ? pricing.cached_input_per_1m : (pricing ? pricing.input_per_1m : 0);
    const cost = pricing ? ((usage.input_tokens - cached) * pricing.input_per_1m + cached * cachedRate + usage.output_tokens * pricing.output_per_1m) / 1e6 : null;
    return { json: { status: 'OK', data: { content, parsed, finish_reason: choice.finish_reason ?? null, model: body.model }, usage, cost_usd: cost, error: null } };
  }
  const vectors = (body.data || []).slice().sort((a, b) => a.index - b.index).map(d => d.embedding);
  const usage = { input_tokens: body.usage?.prompt_tokens ?? 0, output_tokens: 0 };
  const cost = pricing ? usage.input_tokens * pricing.input_per_1m / 1e6 : null;
  return { json: { status: 'OK', data: { vectors, model: body.model, dimensions: vectors[0]?.length ?? null }, usage, cost_usd: cost, error: null } };
}
const retry = code === 408 || code === 409 || code === 429 || code >= 500;
return { json: { status: retry ? 'RETRYABLE_ERROR' : 'PERMANENT_ERROR', data: null, error: { code: body.error?.code || ('HTTP_' + code), message: body.error?.message || ('HTTP ' + code), http_status: code } } };

// Timeout o error de red en una operación NO sensible: reintentable
const msg = $json.error?.message ?? String($json.error ?? 'error de red');
return { json: { status: 'RETRYABLE_ERROR', data: null, error: { code: /timeout/i.test(msg) ? 'TIMEOUT' : 'NETWORK_ERROR', message: msg } } };

